import {
  Object3D,
  PlaneGeometry,
  Mesh,
  Vector2,
} from 'three/webgpu';
import {
  MeshBasicNodeMaterial,
  texture,
  uv,
  add,
  mul,
} from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {Object} placement
 * @property {Array<number>} placement.position
 * @property {Array<number>} placement.rotation
 * @property {Array<number>} placement.scale
 * @property {Object} assets
 * @property {string} assets.imageUrl
 * @property {Object} atlasRegion
 * @property {number} atlasRegion.x
 * @property {number} atlasRegion.y
 * @property {number} atlasRegion.width
 * @property {number} atlasRegion.height
 * @property {Array<Object>} cinematicPrimitives
 * @property {Object} textContent
 * @property {Object} neighborInfo
 */

/**
 * @typedef {Object} NodeContext
 * @property {Object} textureLoader
 * @property {Function} textureLoader.load - (url: string) => THREE.Texture
 * @property {Object} glbLoader
 * @property {Object} primitives - map of primitive functions
 */

/**
 * Creates a billboarded textured plane using an atlas region.
 *
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  // --- Geometry ------------------------------------------------------------
  const rect = config.atlasRegion || {
    x: 0,
    y: 0,
    width: 512,
    height: 320,
  };
  const aspect = rect.width / rect.height;
  const geometry = new PlaneGeometry(aspect, 1, 1, 1);

  // --- Texture -------------------------------------------------------------
  const tex = ctx.textureLoader.load(config.assets.imageUrl);
  tex.flipY = false; // atlas textures are usually not flipped

  // UV transform to sample only the atlas region.
  const atlasSize = new Vector2(tex.image?.width || rect.width, tex.image?.height || rect.height);
  const repeat = new Vector2(rect.width / atlasSize.x, rect.height / atlasSize.y);
  const offset = new Vector2(rect.x / atlasSize.x, rect.y / atlasSize.y);

  const uvNode = add(mul(uv(), repeat), offset);
  const mapNode = texture(tex, uvNode);

  // --- Material ------------------------------------------------------------
  const material = new MeshBasicNodeMaterial();
  material.map = mapNode;
  material.transparent = true;
  material.depthTest = true;
  material.depthWrite = false;

  // --- Mesh ---------------------------------------------------------------
  const mesh = new Mesh(geometry, material);
  mesh.renderOrder = 0;

  // Position / rotation / scale from config
  const [px, py, pz] = config.placement?.position ?? [0, 0, 0];
  const [rx, ry, rz] = config.placement?.rotation ?? [0, 0, 0];
  const [sx, sy, sz] = config.placement?.scale ?? [1, 1, 1];
  mesh.position.set(px, py, pz);
  mesh.rotation.set(rx, ry, rz);
  mesh.scale.set(sx, sy, sz);

  // --- Billboard to camera -------------------------------------------------
  mesh.onBeforeRender = (_renderer, _scene, camera) => {
    mesh.quaternion.copy(camera.quaternion);
  };

  // --- Apply cinematic primitives (none for this node) --------------------
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const primitive of config.cinematicPrimitives) {
      if (primitive && primitive.name && typeof ctx.primitives[primitive.name] === 'function') {
        ctx.primitives[primitive.name](mesh, primitive.params);
      }
    }
  }

  // --- User data -----------------------------------------------------------
  mesh.userData = {
    handlers: {},
    cleanup: () => {
      // Dispose resources
      geometry.dispose();
      material.dispose();
      // Texture is managed by the loader cache; do not dispose it here.

      // Kill any GSAP timelines that might have been created (none in this node)
      gsap.killTweensOf(mesh);
    },
  };

  return mesh;
}
